  "grammar": [
    {
      "title": "El verbo to be",
      "body": "Be significa «ser» o «estar». En presente cambia según el sujeto: I am; you, we y they are; he, she e it is.",
      "en": "I am ready. She is a teacher. They are happy.",
      "es": "Estoy listo. Ella es profesora. Ellos están felices."
    },
    {
      "title": "Presente simple",
      "body": "Úsalo para hábitos y hechos generales. Con he, she e it normalmente añadimos -s. Para preguntar o negar usamos do o does.",
      "en": "I work every day. She works at home. Do you work?",
      "es": "Trabajo cada día. Ella trabaja en casa. ¿Trabajas?"
    },
    {
      "title": "Presente continuo",
      "body": "Se forma con am, is o are + el verbo en -ing. Describe, entre otros usos, una acción que está ocurriendo ahora.",
      "en": "I am learning English. He is reading a book.",
      "es": "Estoy aprendiendo inglés. Él está leyendo un libro."
    },
    {
      "title": "Pasado simple",
      "body": "Habla de acciones terminadas en el pasado. Los verbos regulares llevan -ed; los irregulares cambian de distintas maneras. En preguntas usamos did + verbo base.",
      "en": "We visited a friend. Did you go to school?",
      "es": "Visitamos a un amigo. ¿Fuiste a la escuela?"
    },
    {
      "title": "Futuro con will y going to",
      "body": "Will es común para decisiones espontáneas y predicciones. Be going to se usa, entre otros casos, para planes ya decididos.",
      "en": "I will help you. I am going to study tonight.",
      "es": "Te ayudaré. Voy a estudiar esta noche."
    },
    {
      "title": "Presente perfecto",
      "body": "Se forma con have o has + participio. Conecta una experiencia o acción pasada con el presente sin situarla necesariamente en un momento terminado concreto.",
      "en": "I have visited Canada. She has finished her homework.",
      "es": "He visitado Canadá. Ella ha terminado su tarea."
    }
  ],
